/// The time audits record, shared by the hooks of every contract with an audit.
pub trait AuditClock: Send + Sync + 'static {
    /// The time audits record. The system clock unless overridden.
    fn now(&self) -> crate::prelude::Timestamp {
        crate::prelude::Timestamp(strata_runtime::Clock::now(&strata_runtime::SystemClock).0)
    }
}

/// The quota counters, shared by the hooks of every contract with a quota.
pub trait QuotaCounter: Send + Sync + 'static {
    /// Counts one call against `quota` in the scope of `caller` (`quota.scope`) and stores
    /// the counter, deciding with `quota.check(counter, now)`. An `Err` answers `unavailable`.
    fn count(
        &self,
        quota: &'static crate::quotas::Quota,
        caller: &crate::support::Caller,
    ) -> impl std::future::Future<Output = Result<crate::quotas::QuotaOutcome, String>> + Send;
}

/// The error body every failed call is answered with (`system.generation.errorBody`): type `api-error`, its code the kind of the failure.
#[derive(Debug, Clone, Copy, Default)]
pub struct ErrorBody;

/// A contract error as the error body carries it.
pub trait BodyError: Sized {
    /// The body this error is answered with, before the correlation id is set.
    fn body(&self) -> types::ApiError;

    /// The error a body stands for, when it is one of this contract's: the only error of
    /// the body's kind, with no payload or the body as its payload.
    fn from_body(body: types::ApiError) -> Option<Self>;
}

/// A body of kind `code` with `message` and every optional field left out.
fn error_body(code: types::ErrorCode, message: impl Into<String>) -> types::ApiError {
    types::ApiError {
        code,
        message: message.into(),
        detail: None,
        correlation: String::new(),
    }
}

/// The status and body of a failure the runtime reports itself.
fn runtime_body(code: strata_runtime::FailureCode, message: String) -> (u16, types::ApiError) {
    match code {
        strata_runtime::FailureCode::Unauthenticated => {
            (401, error_body(types::ErrorCode::Unauthenticated, message))
        }
        strata_runtime::FailureCode::Forbidden => {
            (403, error_body(types::ErrorCode::Forbidden, message))
        }
        strata_runtime::FailureCode::InvalidRequest => {
            (422, error_body(types::ErrorCode::Invalid, message))
        }
        strata_runtime::FailureCode::Timeout => {
            (503, error_body(types::ErrorCode::Unavailable, message))
        }
        strata_runtime::FailureCode::Unavailable => {
            (503, error_body(types::ErrorCode::Unavailable, message))
        }
        strata_runtime::FailureCode::Internal => {
            (500, error_body(types::ErrorCode::Internal, message))
        }
        strata_runtime::FailureCode::IdempotencyConflict => {
            (409, error_body(types::ErrorCode::Conflict, message))
        }
    }
}

/// The runtime failure a body that is no contract error is read back as.
fn runtime_code(code: &types::ErrorCode) -> strata_runtime::FailureCode {
    match code {
        types::ErrorCode::Unauthenticated => strata_runtime::FailureCode::Unauthenticated,
        types::ErrorCode::Forbidden => strata_runtime::FailureCode::Forbidden,
        types::ErrorCode::NotFound => strata_runtime::FailureCode::Internal,
        types::ErrorCode::Conflict => strata_runtime::FailureCode::IdempotencyConflict,
        types::ErrorCode::Throttled => strata_runtime::FailureCode::Internal,
        types::ErrorCode::Invalid => strata_runtime::FailureCode::InvalidRequest,
        types::ErrorCode::Unavailable => strata_runtime::FailureCode::Unavailable,
        types::ErrorCode::Internal => strata_runtime::FailureCode::Internal,
    }
}

impl<E> strata_runtime::FailureBody<E> for ErrorBody
where
    E: BodyError + strata_runtime::ContractError,
{
    fn encode(
        failure: strata_runtime::Failure<&E>,
        correlation: &str,
    ) -> serde_json::Result<(u16, Vec<u8>)> {
        let (status, mut body) = match failure {
            strata_runtime::Failure::Contract { error } => (error.status(), error.body()),
            strata_runtime::Failure::Runtime { code, message } => runtime_body(code, message),
        };
        body.correlation = correlation.to_string();
        Ok((status, serde_json::to_vec(&body)?))
    }

    fn decode(_status: u16, bytes: &[u8]) -> Option<strata_runtime::Failure<E>> {
        let body: types::ApiError = serde_json::from_slice(bytes).ok()?;
        let code = runtime_code(&body.code);
        let message = body.message.clone();
        Some(match E::from_body(body) {
            Some(error) => strata_runtime::Failure::Contract { error },
            None => strata_runtime::Failure::Runtime { code, message },
        })
    }
}

