pub trait SubmitJobHandler: Send + Sync + 'static {
    /// Answers one call of contract `submit-job`.
    fn handle(
        &self,
        request: crate::contracts::SubmitJobRequest,
    ) -> impl std::future::Future<
        Output = Result<crate::contracts::SubmitJobResponse, crate::contracts::SubmitJobError>,
    > + Send;
}

impl<T: crate::contracts::Scheduler + Send + Sync + 'static> SubmitJobHandler for T {
    fn handle(
        &self,
        request: crate::contracts::SubmitJobRequest,
    ) -> impl std::future::Future<
        Output = Result<crate::contracts::SubmitJobResponse, crate::contracts::SubmitJobError>,
    > + Send {
        <T as crate::contracts::Scheduler>::submit_job(self, request)
    }
}

/// What the route of contract `submit-job` needs from the deployment beyond its handler.
pub trait SubmitJobHooks: Send + Sync + 'static + QuotaCounter + AuditClock {
    /// Appends an entry of audit `job-submitted-audit` (record `rec-job-audit`) after a successful call of contract `submit-job`. An `Err` answers `internal`.
    fn append_job_submitted_audit(
        &self,
        entry: crate::audits::JobSubmittedAuditEntry,
    ) -> impl std::future::Future<Output = Result<(), String>> + Send;
}

/// Answers one call of contract `submit-job`.
async fn answer_submit_job<S: SubmitJobHandler, H: SubmitJobHooks>(
    handler: &S,
    hooks: &H,
    caller: strata_runtime::Caller,
    request: crate::contracts::SubmitJobRequest,
) -> Result<
    crate::contracts::SubmitJobResponse,
    strata_runtime::Failure<crate::contracts::SubmitJobError>,
> {
    if let Err(broken) = request.validate() {
        return Err(refusal(
            strata_runtime::FailureCode::InvalidRequest,
            broken.to_string(),
        ));
    }
    let principal = principal(&caller);
    if !crate::policies::authorize_submit_job(&principal, &request).is_allowed() {
        return Err(refusal(
            strata_runtime::FailureCode::Forbidden,
            "the policies of contract submit-job refuse this caller",
        ));
    }
    match hooks
        .count(&crate::quotas::QUOTA_SUBMIT, &principal)
        .await
        .map_err(|why| refusal(strata_runtime::FailureCode::Unavailable, why))?
    {
        crate::quotas::QuotaOutcome::Allowed(_) => {}
        crate::quotas::QuotaOutcome::Exceeded { .. } => {
            return Err(strata_runtime::Failure::Contract {
                error: crate::contracts::SubmitJobError::Busy,
            });
        }
    }
    let audited = request.clone();
    let response = handler
        .handle(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })?;
    let entry =
        crate::audits::audit_job_submitted_audit(&principal, &audited, &response, hooks.now())
            .map_err(|why| refusal(strata_runtime::FailureCode::Internal, why.to_string()))?;
    hooks
        .append_job_submitted_audit(entry)
        .await
        .map_err(|why| refusal(strata_runtime::FailureCode::Internal, why))?;
    Ok(response)
}

/// Adds the route of contract `submit-job` to `routes`, answered by `handler` after the checks the specification states for it.
pub fn serve_submit_job<A, S, H>(
    routes: strata_runtime::Routes<A>,
    handler: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: SubmitJobHandler,
    H: SubmitJobHooks,
{
    routes.serve_checked::<SubmitJob, _, _>(
        move |caller: strata_runtime::Caller, request: crate::contracts::SubmitJobRequest| {
            let (handler, hooks) = (handler.clone(), hooks.clone());
            async move { answer_submit_job(&*handler, &*hooks, caller, request).await }
        },
    )
}

