pub fn serve_ping<A, S, H>(
    routes: strata_runtime::Routes<A>,
    handler: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: PingHandler,
    H: PingHooks,
{
    routes.serve_checked::<Ping, _, _>(
        move |caller: strata_runtime::Caller, request: crate::contracts::PingRequest| {
            let (handler, hooks) = (handler.clone(), hooks.clone());
            async move { answer_ping(&*handler, &*hooks, caller, request).await }
        },
    )
}

/// What serves contract `make-report` (Make report) on its own. Every implementation of the trait of component `reports` implements it.
pub trait MakeReportHandler: Send + Sync + 'static {
    /// Answers one call of contract `make-report`.
    fn handle(
        &self,
        request: crate::contracts::MakeReportRequest,
    ) -> impl std::future::Future<
        Output = Result<crate::contracts::MakeReportResponse, crate::contracts::MakeReportError>,
    > + Send;
}

impl<T: crate::contracts::Reports + Send + Sync + 'static> MakeReportHandler for T {
    fn handle(
        &self,
        request: crate::contracts::MakeReportRequest,
    ) -> impl std::future::Future<
        Output = Result<crate::contracts::MakeReportResponse, crate::contracts::MakeReportError>,
    > + Send {
        <T as crate::contracts::Reports>::make_report(self, request)
    }
}

/// What the route of contract `make-report` needs from the deployment beyond its handler.
pub trait MakeReportHooks: Send + Sync + 'static {}

/// The route of contract `make-report` needs no hook of its own.
impl<T: Send + Sync + 'static> MakeReportHooks for T {}

/// Answers one call of contract `make-report`.
async fn answer_make_report<S: MakeReportHandler, H: MakeReportHooks>(
    handler: &S,
    _hooks: &H,
    _caller: strata_runtime::Caller,
    request: crate::contracts::MakeReportRequest,
) -> Result<
    crate::contracts::MakeReportResponse,
    strata_runtime::Failure<crate::contracts::MakeReportError>,
> {
    handler
        .handle(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })
}

